<template>
  <div class="lassox-diagram__CustomizerFieldGroup">
    <CustomizerFieldGroupDropdownButton :fieldGroup="fieldGroup" />

    <div
      v-if="activeFields.length"
      class="lassox-diagram__CustomizerFieldGroup_fields"
    >
      <div
        v-for="field in activeFields"
        :key="field.id"
        class="lassox-diagram__CustomizerFieldGroup_field"
      >
        <div
          class="lassox-diagram__CustomizerFieldGroup_field-legend-color"
          :style="{ backgroundColor: field.legendColor }"
        >
          <div
            v-if="!field.legendColor"
            class="lassox-diagram__CustomizerFieldGroup_field-legend-dot"
          />
        </div>

        <div
          class="lassox-diagram__CustomizerFieldGroup_field-title"
          v-text="field.title"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import CustomizerFieldGroupDropdownButton from './CustomizerFieldGroupDropdownButton.vue'
import type { default as Diagram, Field, FieldGroup } from '../diagram'

@Component({
  components: {
    CustomizerFieldGroupDropdownButton,
  },
})

export default class CustomizerFieldGroup extends Vue {
  @Inject()
  readonly diagram!: Diagram

  @Prop({ type: Object, required: true })
  readonly fieldGroup!: FieldGroup

  get activeFields (): Field[] {
    return this.fieldGroup.fields.filter(field => field.active)
  }
}
</script>

