  &_fields {
    display: flex;
    flex-direction: column;
    margin-top: 6px;
    margin-bottom: -6px;
  }

  &_field {
    display: flex;
    align-items: center;
    padding: 6px 8px;

    &-legend-color {
      position: relative;
      width: 8px;
      height: 8px;
      flex-shrink: 0;
      border-radius: 1px;
    }

    &-legend-dot {
      // $size: 4px;
      // position: absolute;
      // top: calc(50% - #{$size / 2});
      // left: calc(50% - #{$size / 2});
      // width: $size;
      // height: $size;
      // border-radius: 1px;
      // // border-radius: 100%;
