import Vue from 'vue'
import ReactiveMap from './reactive-map'

export default class ReactiveSet<T> {
  constructor (iterable?: Iterable<T>) {
    if (iterable) {
      for (const value of iterable) {
        this.add(value)
      }
    }

    Vue.observable(this)
  }

  private _map = new ReactiveMap<T, T>()

  get size () {
    return this._map.size
  }

  has (value: T) {
    return this._map.has(value)
  }

  add (value: T) {
    return this._map.set(value, value)
  }

  delete (value: T) {
    return this._map.delete(value)
  }

  clear () {
    return this._map.clear()
  }

  entries () {
    return this._map.entries()
  }

  keys () {
    return this._map.keys()
  }

  values () {
    return this._map.values()
  }

  forEach (callbackfn: (value: T, value2: T, set: this) => void) {
    this._map.forEach((value, value2) => callbackfn(value, value2, this))
  }

  *[Symbol.iterator] (): IterableIterator<T> {
    for (const entry of this._map) {
      yield entry[0]
    }
  }
}
