import type { ActiveDiagram, Entity, EntityDefinition, EntityType, Field, Relation, RelationDefinition, RelationType } from '../diagram'
import type { Change, DiagramDataDefinition, EntityEdit, RelationEdit } from './DiagramData'
// import mockSyncData from '../assets/mock-sync-data.json'
import { mapByKey } from '../util/map-util'
import ReactiveSet from '../util/reactive-set'
import _set from 'lodash.set'
import Deferred from '../util/deferred'

export interface CurrentGraph {
  entities: Map<string, Entity>
  relations: Map<string, Relation>
}

export interface NewGraph {
  entities: Map<string, EntityDefinition>
  relations: Map<string, RelationDefinition>
}

export interface ComparisonGraph {
  entities: Map<string, ComparisonGraphEntity>
  relations: Map<string, ComparisonGraphRelation>
}

export interface ComparisonGraphEntity {
  current: Entity | null
  new: EntityDefinition | null
}

export interface ComparisonGraphRelation {
  current: Relation | null
  new: RelationDefinition | null
  fromEntity: ComparisonGraphEntity
  toEntity: ComparisonGraphEntity
}

export interface Addition {
  checked: boolean
  entities: Map<string, {
    entity: EntityDefinition
    fields: DataChangeField[]
    previouslyDeleted: boolean
  }>
  relations: Map<string, {
    relation: RelationDefinition
    fields: DataChangeField[]
    previouslyDeleted: boolean
  }>
}

export interface Removal {
  checked: boolean
  entities: Map<string, {
    entity: Entity
    fields: DataChangeField[]
    isCustom: boolean
  }>
  relations: Map<string, {
    relation: Relation
    fields: DataChangeField[]
    isCustom: boolean
  }>
}

export interface DataChange {
  checked: boolean
  entities: Map<string, {
    entity: Entity
    fields: DataChangeField[]
  }>
  relations: Map<string, {
    relation: Relation
    fields: DataChangeField[]
  }>
}

export interface DataChangeField {
  checked: boolean
  field: Field
  currentValue: any
  currentValueLabel: string
  currentInitialValue: any
  currentInitialValueLabel: string
  newValue: any
  newValueLabel: string
}

type AsyncMethodKeys<T> = { [K in keyof T]: T[K] extends (...args: any) => Promise<any> ? K : never }[keyof T]

function createPromisesObject<K extends AsyncMethodKeys<DiagramUpdater>> (keys: K[]) {
  const promises = {} as { [k in K]: ReturnType<DiagramUpdater[k]> | null }
  for (const key of keys) {
    promises[key] = null
  }
  return promises
}

export default class DiagramUpdater {
  private static defaultGraphCache = new Map<string, Promise<NewGraph | null>>()
  private static inclusiveGraphCache = new Map<string, Promise<NewGraph | null>>()

  private activeDiagram: ActiveDiagram

  private entityTypeOrders: Map<string, number>
  private relationTypeOrders: Map<string, number>

  private __previouslyDeleted: Record<'entities' | 'relations', Set<string>> | null = null

  private promises = createPromisesObject(['load'])

  private cacheKeys = {
    defaultGraph: '',
    inclusiveGraph: '',
  }

  loading = false
  loaded = false

  additions = new ReactiveSet<Addition>()
  removals = new ReactiveSet<Removal>()
  dataChanges = new ReactiveSet<DataChange>()

  updateCount = 0
  defaultCheckedUpdateCount = 0

  constructor (activeDiagram: ActiveDiagram) {
    this.activeDiagram = activeDiagram

    this.entityTypeOrders = new Map(activeDiagram.diagram.entityTypes.items.map((type, order) => [ type.id, order ]))
    this.relationTypeOrders = new Map(activeDiagram.diagram.relationTypes.items.map((type, order) => [ type.id, order ]))

    // for (const type of [ 'default', 'inclusive' ] as const) {
    //   for (const [ key, value ] of Object.entries(mockSyncData[type])) {
    //     this[`${type}GraphCache` as const].set(key, Promise.resolve(this.createNewGraph(value)))
    //   }
    // }

    this.updateCacheKeys()
  }

  private get previouslyDeleted () {
    const cached = this.__previouslyDeleted
    if (cached) return cached

    const previouslyDeleted = {
      entities: new Set<string>(),
      relations: new Set<string>(),
    }

    const handleChange = (change: Change) => {
      if (!change.remove) return
      for (const id of change.remove.entities ?? []) previouslyDeleted.entities.add(id)
      for (const id of change.remove.relations ?? []) previouslyDeleted.relations.add(id)
    }

    for (const change of this.activeDiagram.data.initialData.changes) handleChange(change)
    for (const { change } of this.activeDiagram.data.changes) handleChange(change)

    this.__previouslyDeleted = previouslyDeleted

    return previouslyDeleted
  }

  get hasUpdates () {
    return !!this.updateCount
  }

  clear () {
    this.__previouslyDeleted = null
    this.promises.load = null
    this.loading = false
    this.loaded = false
    this.additions = new ReactiveSet()
    this.removals = new ReactiveSet()
    this.dataChanges = new ReactiveSet()
    this.updateCount = 0
    this.defaultCheckedUpdateCount = 0
  }

  updateCacheKeys () {
    this.cacheKeys.defaultGraph = this.getDefaultGraphCacheKey()
    this.cacheKeys.inclusiveGraph = this.getInclusiveGraphCacheKey()
  }

  async loadIfCached () {
    this.clear()

    return (
      DiagramUpdater.defaultGraphCache.has(this.cacheKeys.defaultGraph)
      && DiagramUpdater.inclusiveGraphCache.has(this.cacheKeys.inclusiveGraph)
    ) ? this.load() : false
  }

  async load () {
    if (!this.activeDiagram.diagram.updater.enabled) return false

    this.clear()

    this.loading = true

    const { promise, resolve } = Deferred<boolean>()
    this.promises.load = promise

    ;(async () => {
      const currentGraph: CurrentGraph = {
        entities: new Map(this.activeDiagram.data.entitiesMap),
        relations: new Map(this.activeDiagram.data.relationsMap),
      }

      const [ defaultGraph, inclusiveGraph ] = await Promise.all([
        this.fetchDefaultGraph(),
        this.fetchInclusiveGraph(),
      ])

      if (promise !== this.promises.load) return resolve(this.promises.load ?? false)

      if (!defaultGraph || !inclusiveGraph) {
        this.activeDiagram.diagram.store.showToast({ content: 'Noget gik galt ved indlæsning af opdateringer.' })
        return resolve(false)
      }

      this.additions = this.getAdditions(currentGraph, defaultGraph)
      this.removals = this.getRemovals(currentGraph, inclusiveGraph)
      this.dataChanges = this.getDataChanges(currentGraph, inclusiveGraph)

      for (const change of [ ...this.additions, ...this.removals, ...this.dataChanges ]) {
        this.updateCount++
        if (change.checked) this.defaultCheckedUpdateCount++
      }

      this.loading = false
      this.loaded = true

      this.promises.load = null

      resolve(true)
    })()

    return await promise
  }

  commit (runLayout = false) {
    const entitiesToAdd: EntityDefinition[] = []
    const relationsToAdd: RelationDefinition[] = []

    const entitiesToRemove: string[] = []
    const relationsToRemove: string[] = []

    const entityEdits: EntityEdit[] = []
    const relationEdits: RelationEdit[] = []

    for (const addition of this.additions) {
      if (!addition.checked) continue
      for (const { entity } of addition.entities.values()) entitiesToAdd.push(entity)
      for (const { relation } of addition.relations.values()) relationsToAdd.push(relation)
    }

    for (const removal of this.removals) {
      if (!removal.checked) continue
      for (const { entity } of removal.entities.values()) entitiesToRemove.push(entity.id)
      for (const { relation } of removal.relations.values()) relationsToRemove.push(relation.id)
    }

    for (const dataChange of this.dataChanges) {
      if (!dataChange.checked) continue
      const handleItem = (item: Entity | Relation, fields: DataChangeField[]) => {
        const newData: Record<string, any> = {}
        for (const field of fields) {
          if (!field.checked) continue
          _set(newData, field.field.dataKey, field.newValue)
        }
        const edits = item.isEntity ? entityEdits : relationEdits
        edits.push({ id: item.id, data: newData })
      }

      for (const { entity, fields } of dataChange.entities.values()) handleItem(entity, fields)
      for (const { relation, fields } of dataChange.relations.values()) handleItem(relation, fields)
    }

    this.activeDiagram.data.commitChange({
      add: {
        entities: entitiesToAdd,
        relations: relationsToAdd,
      },
      remove: {
        entities: entitiesToRemove,
        relations: relationsToRemove,
      },
      edit: {
        entities: entityEdits,
        relations: relationEdits,
      },
    }, { isSync: true })

    const layout = runLayout && this.activeDiagram.diagram.activeDiagram.settings.activeLayout

    if (layout) requestAnimationFrame(() => {
      this.activeDiagram.diagram.eventBus.emit({ name: 'graph.layout', layout, applyToLastChange: true })
    })
  }

  private getDefaultGraphCacheKey () {
    return this.activeDiagram.diagram.mainEntityId
  }

  private getInclusiveGraphCacheKey () {
    return this.activeDiagram.data.entities.map(entity => entity.id).sort().join(';')
  }

  private async fetchDefaultGraph () {
    const cacheKey = this.cacheKeys.defaultGraph

    let promise = DiagramUpdater.defaultGraphCache.get(cacheKey)
    if (promise) return promise

    promise = this.activeDiagram.diagram.fetchDefaultGraph().then(data => {
      if (!data) {
        DiagramUpdater.defaultGraphCache.delete(cacheKey)
        return null
      }

      return this.createNewGraph(data)
    })

    DiagramUpdater.defaultGraphCache.set(cacheKey, promise)

    return promise
  }

  private async fetchInclusiveGraph () {
    const { relationTypes, methods: { getEntityData } } = this.activeDiagram.diagram
    if (!getEntityData) throw 'DiagramUpdater can not be used without defining methods.getEntityData'

    const cacheKey = this.cacheKeys.inclusiveGraph

    let promise = DiagramUpdater.inclusiveGraphCache.get(cacheKey)
    if (promise) return promise

    promise = getEntityData({
      ids: this.activeDiagram.data.entities.map(entity => entity.id),
      relationTypes: relationTypes.items.map(item => item.id),
      parents: 1,
      children: 1,
    }).catch(err => {
      console.error('getEntityData() failed', err)
      DiagramUpdater.inclusiveGraphCache.delete(cacheKey)
      return null
    }).then(data => data && this.createNewGraph(data))

    DiagramUpdater.inclusiveGraphCache.set(cacheKey, promise)

    return promise
  }

  private createNewGraph (data?: DiagramDataDefinition): NewGraph {
    if (data) this.sortResponseData(data)
    return {
      entities: mapByKey(data?.entities ?? [], 'id'),
      relations: mapByKey(data?.relations ?? [], 'id'),
    }
  }

  private sortResponseData (data: DiagramDataDefinition) {
    data.entities?.sort((a, b) => (
      (this.entityTypeOrders.get(a.type) ?? Infinity)
      - (this.entityTypeOrders.get(b.type) ?? Infinity)
    ))

    data.relations?.sort((a, b) => (
      (this.relationTypeOrders.get(a.type) ?? Infinity)
      - (this.relationTypeOrders.get(b.type) ?? Infinity)
    ))
  }

  private createComparisonGraph (currentGraph: CurrentGraph, newGraph: NewGraph) {
    const comparisonGraph: ComparisonGraph = {
      entities: new Map(),
      relations: new Map(),
    }

    for (const id of [ ...currentGraph.entities.keys(), ...newGraph.entities.keys() ]) {
      if (comparisonGraph.entities.has(id)) continue
      comparisonGraph.entities.set(id, {
        current: currentGraph.entities.get(id) ?? null,
        new: newGraph.entities.get(id) ?? null,
      })
    }

    for (const [ id, relation ] of [ ...currentGraph.relations, ...newGraph.relations ]) {
      if (comparisonGraph.relations.has(id)) continue

      const fromEntity = comparisonGraph.entities.get(relation.from)
      const toEntity = comparisonGraph.entities.get(relation.to)

      if (!fromEntity || !toEntity) continue

      comparisonGraph.relations.set(id, {
        current: currentGraph.relations.get(id) ?? null,
        new: newGraph.relations.get(id) ?? null,
        fromEntity,
        toEntity,
      })
    }

    return comparisonGraph
  }

  private createFields (options: {
    type: EntityType | RelationType
    current?: Entity | Relation
    new?: EntityDefinition | RelationDefinition
  }) {
    const currentData = options.current?.data
    const currentInitialData = options.current?.initialState.data
    const newData = options.new?.data

    const getFieldValues = (field: Field, data?: Record<string, any>) => {
      if (!data) return { value: null, valueLabel: '' }

      const value = field.getValue(data) ?? null
      let valueLabel: string

      switch (field.type) {
        case 'text': {
          valueLabel = `${value ?? ''}`
          if (!field.editable && field.formatter) valueLabel = `${field.formatter(value)}`
          break
        }

        case 'boolean': {
          valueLabel = typeof value === 'boolean'
            ? value ? 'Ja' : 'Nej'
            : ''
          break
        }

        default: {
          console.warn(`DiagramUpdater.createFields() did not recognize field type "${field.type}"`)
          valueLabel = `${value ?? ''}`
        }
      }

      return { value, valueLabel }
    }

    const createField = (field: Field): DataChangeField => {
      const {
        value: currentValue,
        valueLabel: currentValueLabel,
      } = getFieldValues(field, currentData)

      const {
        value: currentInitialValue,
        valueLabel: currentInitialValueLabel,
      } = getFieldValues(field, currentInitialData)

      const {
        value: newValue,
        valueLabel: newValueLabel,
      } = getFieldValues(field, newData)

      return {
        checked: true,
        field,
        currentValue,
        currentValueLabel,
        currentInitialValue,
        currentInitialValueLabel,
        newValue,
        newValueLabel,
      }
    }

    return options.type.fields.map(createField)
  }

  private getAdditions (currentGraph: CurrentGraph, defaultGraph: NewGraph) {
    const comparisonGraph = this.createComparisonGraph(currentGraph, defaultGraph)

    comparisonGraph.relations = new Map([ ...comparisonGraph.relations ].sort(([ ,a ], [ ,b ]) => {
      const isEnd = (relation: ComparisonGraphRelation) => !!(relation.fromEntity.current || relation.toEntity.current)
      return (isEnd(a) ? 0 : 1) - (isEnd(b) ? 0 : 1)
    }))

    const subgraphs = new Set<NewGraph>()
    const subgraphsByElementId = new Map<string, NewGraph>()

    const createSubgraph = () => {
      const subgraph = this.createNewGraph()
      subgraphs.add(subgraph)
      return subgraph
    }

    const mergeSubgraphs = (subgraph1: NewGraph, subgraph2: NewGraph) => {
      subgraphs.delete(subgraph2)

      for (const [ id, entity ] of subgraph2.entities) {
        subgraph1.entities.set(id, entity)
        subgraphsByElementId.set(id, subgraph1)
      }

      for (const [ id, relation ] of subgraph2.relations) {
        subgraph1.relations.set(id, relation)
        subgraphsByElementId.set(id, subgraph1)
      }

      subgraph2.entities.clear()
      subgraph2.relations.clear()

      return subgraph1
    }

    for (const [ id, relation ] of comparisonGraph.relations) {
      if (relation.current || !relation.new) continue
      if (!relation.fromEntity.new || !relation.toEntity.new) continue

      let subgraph: NewGraph

      const fromSubgraph = subgraphsByElementId.get(relation.fromEntity.new.id)
      const toSubgraph = subgraphsByElementId.get(relation.toEntity.new.id)

      if (fromSubgraph && toSubgraph) {
        subgraph = mergeSubgraphs(fromSubgraph, toSubgraph)
      } else {
        subgraph = fromSubgraph || toSubgraph || createSubgraph()
        for (const entity of [ relation.fromEntity, relation.toEntity ]) {
          if (entity.current || !entity.new) continue
          subgraph.entities.set(entity.new.id, entity.new)
          subgraphsByElementId.set(entity.new.id, subgraph)
        }
      }

      subgraph.relations.set(id, relation.new)
      subgraphsByElementId.set(id, subgraph)
    }

    const additions = new ReactiveSet<Addition>()
    const addedSubgraphs = new Set<NewGraph>()

    const getEntityType = (type: string) => this.activeDiagram.diagram.entityTypes.get(type)
    const getRelationType = (type: string) => this.activeDiagram.diagram.relationTypes.get(type)

    for (const id of comparisonGraph.relations.keys()) {
      const subgraph = subgraphsByElementId.get(id)
      if (!subgraph || addedSubgraphs.has(subgraph)) continue

      additions.add({
        checked: false,
        entities: new Map([ ...subgraph.entities ].map(([ id, entity ]) => [ id, {
          entity,
          fields: this.createFields({ type: getEntityType(entity.type), new: entity }),
          previouslyDeleted: this.previouslyDeleted.entities.has(id),
        } ])),
        relations: new Map([ ...subgraph.relations ].map(([ id, relation ]) => [ id, {
          relation,
          fields: this.createFields({ type: getRelationType(relation.type), new: relation }),
          previouslyDeleted: this.previouslyDeleted.relations.has(id),
        } ])),
      })

      addedSubgraphs.add(subgraph)
    }

    for (const addition of additions) {
      for (const item of [ ...addition.entities.values(), ...addition.relations.values() ]) {
        if (!item.previouslyDeleted) {
          addition.checked = true
          break
        }
      }
    }

    return additions
  }

  private getRemovals (currentGraph: CurrentGraph, inclusiveGraph: NewGraph) {
    const removals = new ReactiveSet<Removal>()

    for (const [ id, relation ] of currentGraph.relations) {
      if (inclusiveGraph.relations.has(id)) continue

      removals.add({
        checked: !relation.isCustom,
        entities: new Map(),
        relations: new Map([[ id, {
          relation,
          fields: this.createFields({ type: relation.type, current: relation }),
          isCustom: relation.isCustom,
        } ]]),
      })
    }

    return removals
  }

  private getDataChanges (currentGraph: CurrentGraph, inclusiveGraph: NewGraph) {
    const comparisonGraph = this.createComparisonGraph(currentGraph, inclusiveGraph)

    const dataChanges = new ReactiveSet<DataChange>()

    const getChangedFields = (currentItem: Entity | Relation, newItem: EntityDefinition | RelationDefinition) => (
      this.createFields({ type: currentItem.type, current: currentItem, new: newItem })
        .filter(({ currentValue, currentInitialValue, newValue }) => newValue !== currentValue || newValue !== currentInitialValue)
    )

    for (const type of [ 'entities', 'relations' ] as const) {
      const isEntities = type === 'entities'
      const isEntity = (v: unknown): v is ComparisonGraphEntity => isEntities

      for (const [ id, item ] of comparisonGraph[type]) {
        if (!item.current || !item.new) continue

        const fields = getChangedFields(item.current, item.new)
        if (!fields.length) continue

        const dataChange: DataChange = {
          checked: false,
          entities: new Map(),
          relations: new Map(),
        }

        if (isEntity(item)) {
          dataChange.entities.set(id, {
            entity: item.current,
            fields,
          })
        } else {
          dataChange.relations.set(id, {
            relation: item.current,
            fields,
          })
        }

        for (const item of [ ...dataChange.entities.values(), ...dataChange.relations.values() ]) {
          for (const field of item.fields) {
            field.checked = false

            if (field.newValue !== field.currentInitialValue) {
              field.checked = true
              dataChange.checked = true
            }
          }
        }

        dataChanges.add(dataChange)
      }
    }

    return dataChanges
  }
}
