<template>
  <div
    :class="[
      'lassox-diagram__Diagram',
      compact && 'lassox-diagram__Diagram--compact',
    ]"
    tabindex="-1"
    @keydown="onKeyDown"
  >
    <div
      class="lassox-diagram__Diagram-loading-screen"
      :style="{
        opacity: diagram.isLoading ? '1' : '0',
        pointerEvents: diagram.isLoading ? '' : 'none',
      }"
    >
      <LoadingSpinner />
    </div>

    <TopBar v-if="diagram.enableTopBar" :style="{ visibility: (!diagram.hasActiveDiagram || diagram.isLoading) ? 'hidden' : '' }" />

    <div
      class="lassox-diagram__Diagram_graph-columns"
      :style="{ visibility: (!diagram.hasActiveDiagram || diagram.isLoading) ? 'hidden' : '' }"
    >
      <Graph ref="graph" :zoom="diagram.enableZoom" />

      <Customizer v-if="diagram.enableCustomizer" :style="{ visibility: showCustomizer ? '' : 'hidden' }" />

      <Editor v-if="diagram.enableEditing" ref="editor" />
    </div>

    <div class="lassox-diagram__Diagram_dialogs">
      <component
        v-for="(dialog, i) in store.dialogs"
        :key="dialog.id"
        :is="dialog.component"
        v-bind="dialog.props"
        @close="() => store.dialogs.splice(i, 1)"
      />
    </div>

    <div class="lassox-diagram__Diagram_toasts">
      <component
        v-for="(toast, i) in store.toasts"
        :key="toast.id"
        :is="toast.component"
        v-bind="toast.props"
        @close="() => store.toasts.splice(i, 1)"
      />
    </div>

    <TooltipRoot />

    <GraphPrint />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Provide, Watch } from 'vue-property-decorator'
import LoadingSpinner from './LoadingSpinner.vue'
import TopBar from './TopBar.vue'
import Graph from './Graph.vue'
import Customizer from './Customizer.vue'
import Editor from './Editor.vue'
import GraphLegend from './GraphLegend.vue'
import GraphPrint from './GraphPrint.vue'
import TooltipRoot from './TooltipRoot.vue'
import tooltip from '../directives/tooltip'
import Diagram from '../diagram'
import { unwatchRect, watchRect } from '../util/watch-rect'

@Component({
  components: {
    LoadingSpinner,
    TopBar,
    Graph,
    Customizer,
    Editor,
    GraphLegend,
    GraphPrint,
    TooltipRoot,
  },

  directives: {
    tooltip,
  },
})

export default class DiagramVm extends Vue {
  @Provide('diagramVm')
  get diagramVm () { return this }

  @Provide('diagram')
  @Prop({ type: Object, required: true })
  readonly diagram!: Diagram

  @Provide('store')
  @Provide('diagramStore')
  get store () { return this.diagram.store }

  graphVue: Graph | null = null
  editorVue: Editor | null = null

  $el!: HTMLElement

  compact = false
  showCustomizer = true

  userPreferencesWatchKeys = {
    'runLayoutAfterAddition': '',
    'settings.activeFields': '',
    'settings.activeFilters': '',
    'settings.activeLayout': '',
    'settings.enableTaxi': '',
  }

  async created () {
    const { diagram } = this

    diagram.isLoading = true

    /**
     * Autosave userPreferences whenever they change.
     */
    {
      await diagram.userPreferences.load()

      this.$watch(
        () => diagram.userPreferences.runLayoutAfterAddition,
        v => this.userPreferencesWatchKeys['runLayoutAfterAddition'] = JSON.stringify(v),
        { immediate: true },
      )

      this.$watch(
        () => diagram.userPreferences.settings.activeFields,
        v => this.userPreferencesWatchKeys['settings.activeFields'] = JSON.stringify(v),
        { immediate: true, deep: true },
      )

      this.$watch(
        () => diagram.userPreferences.settings.activeFilters,
        v => this.userPreferencesWatchKeys['settings.activeFilters'] = JSON.stringify(v),
        { immediate: true, deep: true },
      )

      this.$watch(
        () => diagram.userPreferences.settings.activeLayout,
        v => this.userPreferencesWatchKeys['settings.activeLayout'] = JSON.stringify(v),
        { immediate: true },
      )

      this.$watch(
        () => diagram.userPreferences.settings.enableTaxi,
        v => this.userPreferencesWatchKeys['settings.enableTaxi'] = JSON.stringify(v),
        { immediate: true },
      )

      this.$watch(
        () => JSON.stringify(this.userPreferencesWatchKeys),
        () => this.diagram.userPreferences.save(),
      )
    }

    await diagram.loadSavedDiagrams()

    if (diagram.initialSavedDiagram) await diagram.load(diagram.initialSavedDiagram)

    if (!diagram.hasActiveDiagram) {
      if (diagram.defaultDiagram.new) {
        await diagram.load()
        diagram.isLoading = false
        return
      }

      const defaultSavedDiagram = diagram.defaultDiagram.savedDiagramId && diagram.savedDiagramsMap.get(diagram.defaultDiagram.savedDiagramId)

      if (defaultSavedDiagram) {
        await diagram.load(defaultSavedDiagram)
        diagram.isLoading = false
        return
      }

      if (diagram.enableDocuments && diagram.savedDiagrams.length) {
        diagram.isLoading = false
        this.store.showLoadDialog()
        return
      }

      await diagram.load()
    }

    diagram.isLoading = false
  }

  mounted () {
    this.graphVue = (this.$refs.graph as Graph | undefined) ?? null
    this.editorVue = (this.$refs.editor as Editor | undefined) ?? null

    watchRect(this.$el, this.onResize)
  }

  updated () {
    this.graphVue = (this.$refs.graph as Graph | undefined) ?? null
    this.editorVue = (this.$refs.editor as Editor | undefined) ?? null
  }

  beforeDestroy () {
    unwatchRect(this.$el, this.onResize)
  }

  onResize ({ width }: DOMRect) {
    this.compact = width <= this.diagram.compactWidth
  }

  onKeyDown (event: KeyboardEvent) {
    if (event.defaultPrevented) return

    const mod = {
      ctrl: event.ctrlKey,
      meta: event.metaKey,
      ctrlOrMeta: event.ctrlKey || event.metaKey,
      shift: event.shiftKey,
      alt: event.altKey,
    }

    const key = event.key.toLowerCase()

    if (mod.ctrlOrMeta && key === 'p') {
      event.preventDefault()
      this.store.showPrintDialog('print')
      return
    }
  }

  @Watch('compact')
  onCompactChanged () {
    this.showCustomizer = !this.compact
  }
}
</script>

<style lang="scss">
.lassox-diagram__Diagram {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  font-family: inherit;
  touch-action: none;

  &,
  * {
    overscroll-behavior: none;
    scrollbar-width: thin;
    scrollbar-width: 4px;
    box-sizing: border-box;

    &::-webkit-scrollbar {
      width: 4px;
      height: 4px;
      background-color: rgba(0, 0, 0, 0.125);
    }

    &::-webkit-scrollbar-thumb {
      background-color: rgba(0, 0, 0, 0.25);
    }

    &::-webkit-scrollbar-thumb:hover {
      background-color: rgba(0, 0, 0, 0.5);
    }
  }

  &, p, ul, ol, li, h1, h2, h3, h4, h5, h6 {
    margin: 0;
    color: rgba(black, 0.68);
    font-family: inherit;
    font-size: 14px;
    line-height: 24px;
  }

  a {
    color: #FF8E61;
    text-decoration: none;

    &:hover {
      text-decoration: underline;
    }
  }

  &-loading-screen {
    position: absolute;
    z-index: 2;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    background-color: white;
    transition: opacity 100ms;

    .lassox-diagram__LoadingSpinner {
      flex-shrink: 0;
      flex-grow: 0;
      margin: auto;
    }
  }

  .lassox-diagram__TopBar {
    position: relative;
    z-index: 1;
  }

  &_graph-columns {
    position: relative;
    z-index: 0;
    display: flex;
    height: 1px;
    flex-grow: 1;
  }

  &_dialogs {
    position: absolute;
    z-index: 1;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;
  }

  &_toasts {
    position: absolute;
    z-index: 1;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    pointer-events: none;
  }
}
</style>
