<template>
  <div
    class="lassox-diagram__GraphNode"
    :style="style"
  >
    <div
      v-if="labels.length"
      class="lassox-diagram__GraphNode-labels-wrapper"
      :style="labelsStyle"
    >
      <Icon
        v-if="entity.type.icon"
        :icon="entity.type.icon"
        :light="brightnessTypes.labels.fg === 'light'"
      />

      <div class="lassox-diagram__GraphNode-labels">
        <div
          v-for="(field, i) in labels"
          :key="i"
          class="lassox-diagram__GraphNode-field"
        >
          <div
            v-if="field.legendColor"
            class="lassox-diagram__GraphNode-field-legend-color"
            :style="{ backgroundColor: field.legendColor }"
          />

          <div
            class="lassox-diagram__GraphNode-field-value"
            v-html="field.html"
          />
        </div>
      </div>
    </div>

    <div
      v-if="fieldGroups.length"
      class="lassox-diagram__GraphNode-fields"
      :style="fieldsStyle"
    >
      <div
        v-for="(fieldGroup, i) in fieldGroups"
        :key="i"
        :class="[
          'lassox-diagram__GraphNode-field-group',
          fieldGroup.title && 'lassox-diagram__GraphNode-field-group--has-title',
        ]"
        :style="{
          borderStyle: fieldsStyle.borderStyle,
          borderColor: fieldsStyle.borderColor,
        }"
      >
        <div
          v-if="fieldGroup.title"
          class="lassox-diagram__GraphNode-field-group-title"
          v-text="fieldGroup.title"
        />

        <div
          v-for="(field, i) in fieldGroup.fields"
          :key="i"
          class="lassox-diagram__GraphNode-field"
        >
          <div
            v-if="field.legendColor"
            class="lassox-diagram__GraphNode-field-legend-color"
            :style="{ backgroundColor: field.legendColor }"
          />

          <div
            class="lassox-diagram__GraphNode-field-value"
            v-html="field.html"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import type DiagramVm from './Diagram.vue'
import type { default as Diagram, EntityStyle } from '../diagram'
import type Graph from './Graph.vue'
import type cytoscape from 'cytoscape'
import { unwatchRect, watchRect } from '../util/watch-rect'
import { getPercBrightness } from '../util/color'
import iro from '@jaames/iro'
import Icon from './Icon.vue'
import htmlSafeString from '../util/html-safe-string'

interface FieldGroup {
  title?: string
  fields: Field[]
}

interface Field {
  legendColor?: string | null
  html: string
}

const textColorsByBrightness = {
  light: 'rgba(255, 255, 255, 0.92)',
  dark: 'rgba(0, 0, 0, 0.68)',
}

const getColorBrightness = (color: string) => getPercBrightness(new iro.Color(color)) > 165 ? 'light' : 'dark'

const getOppositeBrightness = (brightnessType: 'light' | 'dark') => brightnessType === 'light' ? 'dark' : 'light'

@Component({
  components: {
    Icon,
  },
})

export default class GraphNode extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly graphVm!: Graph

  @Prop({ type: String, required: true })
  readonly id!: string

  log = console.log

  el?: HTMLElement
  node?: cytoscape.NodeSingular
  position: cytoscape.Position = { x: 0, y: 0 }
  hidden = false
  selected = false

  labels: Field[] = []
  fieldGroups: FieldGroup[] = []

  get entity () {
    return this.diagram.activeDiagram.data.entitiesMap.get(this.id)
  }

  get entityStyle (): Required<EntityStyle> {
    const entityStyle = (
      this.graphVm.printMode
      ? this.entity?.builtPrintStyle
      : this.entity?.builtPreviewStyle ?? this.entity?.builtStyle
    ) ?? {}

    return {
      minWidth: entityStyle.minWidth ?? 160,
      maxWidth: entityStyle.maxWidth ?? 480,
      borderWidth: entityStyle.borderWidth ?? 0,
      borderStyle: entityStyle.borderStyle ?? 'solid',
      borderColor: entityStyle.borderColor ?? '#000000',
      labelsBackgroundColor: entityStyle.labelsBackgroundColor ?? '#ffffff',
      backgroundColor: entityStyle.backgroundColor ?? '#ffffff',
    }
  }

  get borderRadius () {
    const outer = 4
    return {
      outer,
      inner: outer - this.entityStyle.borderWidth,
    }
  }

  get style () {
    const style = this.entityStyle
    const { position } = this

    return {
      transform: `translate(-50%, -50%) translate(${position.x}px, ${position.y}px)`,
      visibility: this.hidden ? 'hidden' : '',
      minWidth: `${style.minWidth}px`,
      maxWidth: typeof style.maxWidth === 'number' ? `${style.maxWidth}px` : style.maxWidth,
      borderWidth: `${style.borderWidth}px`,
      borderStyle: style.borderStyle,
      borderColor: style.borderColor,
      borderRadius: this.borderRadius.outer,
      boxShadow: this.selected ? '0 0 2px 2px #ffa07a' : '',
    }
  }

  get brightnessTypes () {
    const labelsBg = getColorBrightness(this.entityStyle.labelsBackgroundColor)
    const fieldsBg = getColorBrightness(this.entityStyle.backgroundColor)

    return {
      labels: {
        fg: getOppositeBrightness(labelsBg),
        bg: labelsBg,
      },
      fields: {
        fg: getOppositeBrightness(fieldsBg),
        bg: fieldsBg,
      },
    } as const
  }

  get labelsStyle () {
    const style = this.entityStyle
    const backgroundColor = style.labelsBackgroundColor

    return {
      borderTopLeftRadius: `${this.borderRadius.inner}px`,
      borderTopRightRadius: `${this.borderRadius.inner}px`,
      borderBottomLeftRadius: `${this.borderRadius.inner}px`,
      borderBottomRightRadius: `${this.borderRadius.inner}px`,
      ...(this.fieldGroups.length ? {
        borderBottomLeftRadius: '0',
        borderBottomRightRadius: '0',
      } : {}),
      color: textColorsByBrightness[this.brightnessTypes.labels.fg],
      backgroundColor,
    }
  }

  get fieldsStyle () {
    const style = this.entityStyle
    const backgroundColor = style.backgroundColor

    return {
      borderWidth: '0',
      borderTopWidth: this.style.borderWidth,
      borderStyle: this.style.borderStyle,
      borderColor: this.style.borderColor,
      borderTopLeftRadius: `${this.borderRadius.inner}px`,
      borderTopRightRadius: `${this.borderRadius.inner}px`,
      borderBottomLeftRadius: `${this.borderRadius.inner}px`,
      borderBottomRightRadius: `${this.borderRadius.inner}px`,
      ...(this.labels.length ? {
        borderTopLeftRadius: '0',
        borderTopRightRadius: '0',
      } : {}),
      color: textColorsByBrightness[this.brightnessTypes.fields.fg],
      backgroundColor,
    }
  }

  created () {
    this.$watch(
      () => this.entity,
      () => {
        this.node?.off('position', this.onPosition)
        this.node?.off('data', this.onData)

        this.node = this.graphVm._graph?.nodes().$id(this.id)

        this.onPosition()
        this.node?.on('position', this.onPosition)

        this.onData()
        this.node?.on('data', this.onData)
      },
      { immediate: true },
    )
  }

  mounted () {
    const el = this.el = this.$el as HTMLElement

    this.$watch(
      () => this.entity,
      () => {
        unwatchRect(el, this.onRectChanged)
        watchRect(el, this.onRectChanged)
      },
      { immediate: true },
    )
  }

  beforeDestroy () {
    if (this.el) unwatchRect(this.el, this.onRectChanged)
  }

  updateFields () {
    this.labels = []
    this.fieldGroups = []

    if (!this.entity) return

    const data = this.entity.previewData || this.entity.data

    for (const fieldGroup of this.entity.fieldGroups) {
      const fields: Field[] = []

      for (const field of fieldGroup.fields) {
        if (!field.active) continue

        const legendColor = field.addToLegend ? field.legendColor : null
        const value = field.getValue(data)

        let html = ''

        if (field.htmlFormatter) {
          html = String(field.htmlFormatter(value) ?? '')
        } else {
          html = htmlSafeString(String((field.formatter ? field.formatter(value) : value) ?? ''))
        }

        if (!html) continue

        const array = field.isEntityLabel ? this.labels : fields

        array.push({ legendColor, html })
      }

      if (fields.length) {
        this.fieldGroups.push({
          title: fieldGroup.showTitleInGraph ? fieldGroup.title : undefined,
          fields,
        })
      }
    }

    if (!this.labels.length) {
      this.labels.push({ html: htmlSafeString(this.entity.type.labels.singular) })
    }
  }

  onPosition () {
    this.position = { ...this.node?.position() ?? { x: 0, y: 0 } }
  }

  onData () {
    this.updateFields()
    const data = this.node?.data()
    this.hidden = !!(data.hidden || data.hiddenByFilter)
    this.selected = !this.graphVm.printMode && !!data.selected
  }

  onRectChanged (rect: DOMRect, oldRect: DOMRect | null) {
    if (!this.node) return
    if (oldRect && rect.width === oldRect.width && rect.height === oldRect.height) return

    const scaling = (this.graphVm._graph?.zoom() ?? 1) / this.graphVm.scaling

    const width = Math.round(rect.width / scaling)
    const height = Math.round(rect.height / scaling)

    const { width: oldWidth, height: oldHeight } = this.node.data()
    if (width === oldWidth && height === oldHeight) return

    this.node.off('data', this.onData)
    this.node.data({ width, height })
    this.node.on('data', this.onData)

    this.node.emit('lx:node-resize')
  }
}
</script>

<style lang="scss">
.lassox-diagram__GraphNode {
  position: absolute;
  top: -100vh;
  left: -100vw;
  box-sizing: border-box;
  min-width: 160px;
  max-width: 480px;
  min-height: 32px;
  border-radius: 4px;
  user-select: none;
  pointer-events: none;
  -webkit-print-color-adjust: exact;

  &-labels-wrapper, &-fields {
    padding: 8px 0;
    // border-radius: inherit;
  }

  &-labels-wrapper:not(:last-child) {
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
  }

  &-fields:not(:first-child) {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }

  &-labels-wrapper {
    display: flex;
    align-items: center;
    padding-left: 8px;
    padding-right: 8px;
  }

  .lassox-diagram__Icon {
    box-sizing: content-box;
    padding-right: 8px;
  }

  &-field-group {
    display: flex;
    flex-direction: column;
    padding: 0 8px;
    border-width: 0;

    & + & {
      margin-top: 8px;
    }

    &-title {
      color: #212121;
      font-weight: 500;
    }
  }

  &-field-group + &-field-group--has-title,
  &-field-group--has-title + &-field-group {
    padding-top: 8px;
    border-top-width: 1px;
    margin-top: 8px;
  }

  &-field {
    display: flex;
    align-items: center;
    margin: -2px 0;

    & + & {
      margin-top: 8px - 2px;
    }

    &-legend-color {
      width: 8px;
      height: 8px;
      flex-shrink: 0;
      margin-right: 8px;
      border-radius: 1px;
      -webkit-print-color-adjust: exact;
    }

    &-value {
      flex-grow: 1;
      font-size: 14px;
      line-height: 20px;
    }
  }
}
</style>
