<script lang="ts">
import Vue, { VNode } from 'vue'

const CommaJoin = Vue.extend({
  functional: true,
  render: (h, ctx) => {
    const vnodes: VNode[] = []
    const lastI = ctx.children.length - 1
    for (const [ i, vnode ] of ctx.children.entries()) {
      if (i) vnodes.push(h('span', i === lastI ? ' og ' : ', '))
      vnodes.push(vnode)
    }
    return vnodes
  },
})

export default CommaJoin
</script>
