<template>
  <Dialog
    class="lassox-diagram__ConfirmResetDialog"
    :dismissable="true"
    title="Nulstil diagrammet?"
    content="Dette vil fjerne eventuelle ændringer og nulstille dine indstillinger. Vil du fortsætte?"
    :onClose="dismiss"
  >
    <template v-slot:actions>
      <ButtonGroup align="right">
        <Button
          label="Fortryd"
          @click="dismiss"
        />

        <Button
          label="Fortsæt"
          type="primary"
          @click="confirm"
        />
      </ButtonGroup>
    </template>
  </Dialog>
</template>

<script lang="ts">
import { Vue, Component, Prop } from 'vue-property-decorator'
import Dialog from './Dialog.vue'
import ButtonGroup from './ButtonGroup.vue'
import Button from './Button.vue'

@Component({
  components: {
    Dialog,
    ButtonGroup,
    Button,
  },
})

export default class ConfirmResetDialog extends Vue {
  @Prop(Function)
  readonly onConfirm?: () => void

  @Prop(Function)
  readonly onDismiss?: () => void

  close () {
    this.$emit('close')
  }

  confirm () {
    this.close()
    this.onConfirm?.()
  }

  dismiss () {
    this.close()
    this.onDismiss?.()
  }
}
</script>
