<template>
  <div
    class="lassox-diagram__GraphEdge"
    :style="style"
  >
    <div
      v-for="(label, i) in labels"
      :key="i"
      class="lassox-diagram__GraphEdge-label"
      v-html="label.html"
    />
  </div>
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import type DiagramVm from './Diagram.vue'
import type { default as Diagram, Relation, CustomTaxi } from '../diagram'
import type Graph from './Graph.vue'
import type cytoscape from 'cytoscape'
import cloneDeep from 'lodash.clonedeep'
import htmlSafeString from '../util/html-safe-string'

function getDistance (a: cytoscape.Position, b: cytoscape.Position) {
  const x = b.x - a.x
  const y = b.y - a.y
  return Math.sqrt(x * x + y * y)
}

function getRadAngle (a: cytoscape.Position, b: cytoscape.Position) {
  return Math.atan2(b.y - a.y, b.x - a.x)
}

function getDistWeight (source: cytoscape.Position, target: cytoscape.Position, point: cytoscape.Position) {
  const lineAngle = getRadAngle(source, target)
  const pointAngle = getRadAngle(source, point)
  const angleDiff = pointAngle - lineAngle

  const lineLength = getDistance(source, target)
  const pointDistance = getDistance(source, point)

  const distMult = Math.sin(angleDiff)
  const distance = pointDistance * distMult

  const weightMult = Math.cos(angleDiff)
  const weight = (pointDistance * weightMult) / lineLength

  return {
    distance,
    weight,
  }
}

@Component({})

export default class GraphEdge extends Vue {
  @Inject()
  readonly diagramVm!: DiagramVm

  @Inject()
  readonly diagram!: Diagram

  @Inject()
  readonly graphVm!: Graph

  @Prop({ type: String, required: true })
  readonly id!: string

  edge?: cytoscape.EdgeSingular = undefined
  fromNode?: cytoscape.NodeSingular = undefined
  toNode?: cytoscape.NodeSingular = undefined

  sourceNodePosition: cytoscape.Position = { x: 0, y: 0 }
  targetNodePosition: cytoscape.Position = { x: 0, y: 0 }

  sourceEndpointPosition: cytoscape.Position = { x: 0, y: 0 }
  targetEndpointPosition: cytoscape.Position = { x: 0, y: 0 }

  labelPosition: cytoscape.Position = { x: 0, y: 0 }

  customPath: any = null
  customTaxi: any = null
  hidden = false
  selected = false

  get relation () {
    return this.diagram.activeDiagram.data.relationsMap.get(this.id)
  }

  get style () {
    const { labelPosition } = this

    return {
      zIndex: this.selected ? '1' : '',
      transform: `translate(-50%, -50%) translate(${labelPosition.x}px, ${labelPosition.y}px)`,
      visibility: (this.hidden || !this.labels.length) ? 'hidden' : '',
      color: (
        this.selected ? '#ffa07a' :
        'rgba(0, 0, 0, 0.68)'
      ),
    }
  }

  get labels () {
    if (!this.relation) return []

    const labels: ({
      html: string,
    })[] = []

    for (const fieldGroup of this.relation.fieldGroups) {
      for (const field of fieldGroup.fields) {
        if (!field.active || !field.isRelationLabel) continue

        const value = field.getValue(this.relation.previewData ?? this.relation.data)

        let html = ''

        if (field.htmlFormatter) {
          html = String(field.htmlFormatter(value) ?? '')
        } else {
          html = htmlSafeString(String((field.formatter ? field.formatter(value) : value) ?? ''))
        }

        if (!html) continue

        labels.push({ html })
      }
    }

    return labels
  }

  mounted () {
    // this.graphVm._graph?.on('resize', this.onPosition)

    this.$watch(
      () => this.relation,
      () => {
        this.fromNode?.off('position bounds', this.onNodePosition)
        this.toNode?.off('position bounds', this.onNodePosition)
        this.edge?.off('data style', this.onData)

        this.edge = this.graphVm._graph?.edges().$id(this.id)
        this.fromNode = this.relation && this.graphVm._graph?.nodes().$id(this.relation.from)
        this.toNode = this.relation && this.graphVm._graph?.nodes().$id(this.relation.to)

        this.onNodePosition()
        this.fromNode?.on('position bounds', this.onNodePosition)
        this.toNode?.on('position bounds', this.onNodePosition)

        this.onData()
        this.edge?.on('data style', this.onData)
      },
      { immediate: true },
    )

    requestAnimationFrame(() => {
      this.$watch(
        () => [ this.customPath, this.customTaxi ],
        this.onCustomTaxiChange,
        { immediate: true },
      )

      // this.$watch(
      //   () => [
      //     this.sourceNodePosition.x,
      //     this.sourceNodePosition.y,
      //     this.targetNodePosition.x,
      //     this.targetNodePosition.y,
      //   ],
      //   this.updateEndpointPositions,
      //   { immediate: true },
      // )

      // this.$watch(
      //   () => [
      //     this.sourceEndpointPosition.x,
      //     this.sourceEndpointPosition.y,
      //     this.targetEndpointPosition.x,
      //     this.targetEndpointPosition.y,
      //   ],
      //   this.updateLabelPosition,
      //   { immediate: true },
      // )
    })
  }

  beforeDestroy () {
    // this.graphVm._graph?.off('resize', this.onPosition)

    this.fromNode?.off('position bounds', this.onNodePosition)
    this.toNode?.off('position bounds', this.onNodePosition)
    this.edge?.off('data style', this.onData)
  }

  onData () {
    const oldCustomTaxi = this.customTaxi

    const data = this.edge?.data()
    const relation: Relation = data.relation
    const builtRelationStyle = relation.builtPreviewStyle ?? relation.builtStyle
    this.customPath = data.customPath ?? null
    this.customTaxi = builtRelationStyle.taxi ? data.customTaxi ?? null : null
    this.hidden = !!(data.hidden || data.hiddenByFilter)
    this.selected = !this.graphVm.printMode && !!data.selected

    if (this.customTaxi !== oldCustomTaxi) this.buildCustomTaxi()
  }

  onNodePosition () {
    if (!this.edge) return

    this.updateNodePositions()
    this.updateEndpointPositions()
    this.updateLabelPosition()
    this.fixCustomTaxi()
    this.buildCustomTaxi()
  }

  fixCustomTaxi () {
    const { edge } = this
    if (!edge) return

    const customTaxi: CustomTaxi | null = cloneDeep(edge.data('customTaxi')) ?? null
    if (!customTaxi) return

    const { from, to, segmentPoints } = customTaxi

    const getRect = (node: cytoscape.NodeSingular) => {
      const { x, y } = node.position()
      const width = node.width()
      const height = node.height()
      return {
        width,
        height,
        x: {
          left: x - width / 2,
          center: x,
          right: x + width / 2,
        },
        y: {
          top: y - height / 2,
          center: y,
          bottom: y + height / 2,
        },
      }
    }

    const getEndpoint = (type: 'source' | 'target') => {
      const rect = getRect(edge[type]())
      const { x, y } = customTaxi[type === 'source' ? 'from' : 'to']
      return {
        x: rect.x.center + rect.width * x,
        y: rect.y.center + rect.height * y,
      }
    }

    let changed = false

    for (const [ side, endpoint, point ] of [
      [ from.side, getEndpoint('source'), segmentPoints[0] ],
      [ to.side, getEndpoint('target'), segmentPoints[segmentPoints.length - 1] ],
    ] as const) {
      const axis = (side === 'left' || side === 'right') ? 'x' : 'y'
      const crossAxis = axis === 'x' ? 'y' : 'x'

      if (point[crossAxis] !== endpoint[crossAxis]) {
        changed = true
        point[crossAxis] = endpoint[crossAxis]
      }
    }

    if (changed) edge.data('customTaxi', customTaxi)
  }

  buildCustomTaxi () {
    const { edge } = this
    if (!edge) return

    const customTaxi: CustomTaxi | null = edge.data('customTaxi')
    const relation: Relation = edge.data('relation')
    const builtRelationStyle = relation.builtPreviewStyle ?? relation.builtStyle

    if (!customTaxi || !builtRelationStyle.taxi) {
      edge.data('builtCustomTaxi', null)
      return
    }

    const getEndpoint = (type: 'source' | 'target') => {
      const node = edge[type]()
      const nodePos = node.position()

      const customTaxiEndpoint = customTaxi[type === 'source' ? 'from' : 'to']

      return {
        side: customTaxiEndpoint.side,
        axis: (customTaxiEndpoint.side === 'left' || customTaxiEndpoint.side === 'right') ? 'x' as const : 'y' as const,
        x: nodePos.x + node.width() * customTaxiEndpoint.x,
        y: nodePos.y + node.height() * customTaxiEndpoint.y,
      }
    }

    const sourceEndpoint = getEndpoint('source')
    const targetEndpoint = getEndpoint('target')

    let segmentPoints = customTaxi.segmentPoints

    for (const type of [ 'source', 'target' ] as const) {
      const endpoint = type === 'source' ? sourceEndpoint : targetEndpoint

      if (type === 'target') segmentPoints.reverse()

      let doneFiltering = false

      segmentPoints = segmentPoints.filter(point => {
        if (doneFiltering) return true

        if (point.x === endpoint.x && point.y === endpoint.y) return false

        doneFiltering = true
        return true
      })

      if (type === 'target') segmentPoints.reverse()
    }

    if (!segmentPoints.length) {
      const sourceAxis = sourceEndpoint.axis

      segmentPoints = sourceEndpoint.axis === targetEndpoint.axis
        ? [
          {
            x: sourceEndpoint.x,
            y: sourceEndpoint.y,
            [sourceAxis]: (sourceEndpoint[sourceAxis] + targetEndpoint[sourceAxis]) / 2,
          },
          {
            x: targetEndpoint.x,
            y: targetEndpoint.y,
            [sourceAxis]: (sourceEndpoint[sourceAxis] + targetEndpoint[sourceAxis]) / 2,
          },
        ]
        : [
          {
            x: sourceEndpoint.x,
            y: sourceEndpoint.y,
            [sourceAxis]: targetEndpoint[sourceAxis],
          },
        ]
    }

    const distances: number[] = []
    const weights: number[] = []

    for (const point of segmentPoints) {
      const { distance, weight } = getDistWeight(edge.source().position(), edge.target().position(), point)
      distances.push(distance)
      weights.push(weight)
    }

    edge.data('builtCustomTaxi', {
      sourceEndpoint: `${customTaxi.from.x * 100}% ${customTaxi.from.y * 100}%`,
      targetEndpoint: `${customTaxi.to.x * 100}% ${customTaxi.to.y * 100}%`,
      segmentDistances: distances,
      segmentWeights: weights,
    })
  }

  updateNodePositions () {
    if (this.fromNode) {
      const { x, y } = this.fromNode.position()
      this.sourceNodePosition.x = x
      this.sourceNodePosition.y = y
    }

    if (this.toNode) {
      const { x, y } = this.toNode.position()
      this.targetNodePosition.x = x
      this.targetNodePosition.y = y
    }
  }

  onCustomTaxiChange () {
    requestAnimationFrame(() => {
      this.updateEndpointPositions()
      this.updateLabelPosition()
    })
  }

  updateEndpointPositions () {
    if (!this.edge) return

    const { x: sourceX, y: sourceY } = this.edge.sourceEndpoint()
    this.sourceEndpointPosition.x = sourceX
    this.sourceEndpointPosition.y = sourceY

    const { x: targetX, y: targetY } = this.edge.targetEndpoint()
    this.targetEndpointPosition.x = targetX
    this.targetEndpointPosition.y = targetY
  }

  updateLabelPosition () {
    if (!this.edge) return

    try {
      const { x, y } = this.edge.midpoint()
      this.labelPosition.x = x
      this.labelPosition.y = y
    } catch {
      // ...
    }
  }
}
</script>

<style lang="scss">
.lassox-diagram__GraphEdge {
  position: absolute;
  top: -100vh;
  left: -100vw;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  max-width: 200px;
  padding: 0 4px;
  border-radius: 4px;
  text-align: center;
  background-color: white;
  user-select: none;
  pointer-events: none;
  -webkit-print-color-adjust: exact;

  &-label {
    margin: -2px 0;
    font-size: 14px;
    line-height: 20px;

    & + & {
      margin-top: 8px - 2px;
    }
  }
}
</style>
