<template>
  <transition
    appear
    @enter="onEnter"
    @leave="onLeave"
  >
    <div class="lassox-diagram__Toast">
      <div
        ref="boxEl"
        class="lassox-diagram__Toast-box"
      >
        <LoadingSpinner
          v-if="showLoadingSpinner"
          preset="small"
        />

        <div
          v-if="content"
          class="lassox-diagram__Toast-content"
          v-text="content"
        />

        <IconButton
          v-if="dismissable"
          icon="close"
          light
          @click="close"
        />
      </div>
    </div>
  </transition>
</template>

<script lang="ts">
import { Vue, Component, Prop, Watch, Ref } from 'vue-property-decorator'
import LoadingSpinner from './LoadingSpinner.vue'
import IconButton from './IconButton.vue'
import { unwatchRect, watchRect } from '../util/watch-rect'

@Component({
  components: {
    LoadingSpinner,
    IconButton,
  },
})

export default class Toast extends Vue {
  @Ref()
  readonly boxEl!: HTMLElement

  @Prop({ type: String })
  readonly content?: string

  @Prop({ type: Boolean, default: true })
  readonly dismissable!: boolean

  @Prop({ type: Number, default: 5000 })
  readonly duration!: number

  @Prop({ type: Boolean, default: false })
  readonly showLoadingSpinner!: boolean

  $el!: HTMLElement

  height = 0

  closed = false
  timeoutId: number | null = null

  onEnter () {
    watchRect(this.boxEl, this.onResize)

    this.$watch(
      () => this.height,
      () => this.$el.style.height = `${this.height + 16}px`,
      { immediate: true },
    )
  }

  onLeave () {
    unwatchRect(this.boxEl, this.onResize)

    this.$el.style.height = `0`
  }

  onResize (rect: DOMRect) {
    this.height = rect.height
  }

  clearTimeout () {
    if (this.timeoutId !== null) clearTimeout(this.timeoutId)
  }

  setTimeout () {
    this.clearTimeout()
    if (this.duration > 0) this.timeoutId = setTimeout(this.close, this.duration)
  }

  close () {
    if (closed) return
    this.closed = true
    this.clearTimeout()
    this.$emit('close')
  }

  @Watch('duration', { immediate: true })
  onDurationChanged () {
    this.setTimeout()
  }
}
</script>

