    background-color: #353b3f;
    box-shadow: 0 2px 5px 0 rgba(black, 0.1);
    user-select: none;
    pointer-events: all;
  }

  .lassox-diagram__LoadingSpinner,
  .lassox-diagram__IconButton {
    flex-grow: 0;
    flex-shrink: 0;
  }

  .lassox-diagram__LoadingSpinner {
    margin: -4px;
    margin-right: 12px;
  }

  &-content {
    min-width: 0;
    flex-grow: 1;
    flex-shrink: 1;
    margin: -2px 0;
    font-size: 14px;
    line-height: 20px;
  }

  .lassox-diagram__IconButton {
    margin: -4px;
    margin-left: 12px;
  }
}

// Transition
.lassox-diagram__Toast {
  &.v-enter-active {
    transition: height 250ms ease-out;
  }

  &.v-leave-active {
    transition: height 125ms ease-out;
  }

