<template>
  <BaseButton
    class="lassox-diagram__DropdownMenuItem"
    :icon="icon"
    :iconColor="iconColor"
    :label="label"
    :trailingIcon="trailingIcon"
    :trailingIconColor="trailingIconColor"
    :disabled="disabled"
    tabindex="0"
    v-on="{
      ...$listeners,
      click: onClick,
      mouseover: onMouseOver,
      mouseout: onMouseOut,
    }"
  />
</template>

<script lang="ts">
import { Vue, Component, Prop, Inject } from 'vue-property-decorator'
import BaseButton from './BaseButton.vue'
import DropdownMenu from './DropdownMenu.vue'

@Component({
  components: {
    BaseButton,
  },
})

export default class DropdownMenuItem extends Vue {
  @Inject()
  readonly dropdownMenuVm!: DropdownMenu

  @Prop(String)
  readonly icon?: string

  @Prop(String)
  readonly iconColor?: string

  @Prop({ type: String, required: true })
  readonly label!: string

  @Prop(String)
  readonly trailingIcon?: string

  @Prop(String)
  readonly trailingIconColor?: string

  @Prop({ type: Boolean, default: false })
  readonly disabled!: boolean

  @Prop({ type: Boolean, default: true })
  readonly closeMenuOnClick!: boolean

  isMousedOver = false
  longMouseOverPromise: Promise<void> | null = null

  onClick (event: MouseEvent) {
    this.$emit('click', event)
    if (this.closeMenuOnClick) {
      this.dropdownMenuVm.close?.()

      for (const menu of this.dropdownMenuVm.ancestorDropdownMenus) {
        if (!menu.close) break
        menu.close()
      }
    }
  }

  onMouseOver (event: MouseEvent) {
    this.$emit('mouseover', event)
    this.isMousedOver = true

    const promise = this.longMouseOverPromise = new Promise(resolve => setTimeout(resolve, 250))

    promise.then(() => {
      if (this.longMouseOverPromise !== promise) return
      this.longMouseOverPromise = null
      if (this.isMousedOver) this.$emit('longmouseover')
    })
  }

  onMouseOut (event: MouseEvent) {
    this.$emit('mouseout', event)
    this.isMousedOver = false
  }
}
</script>

<style lang="scss">
.lassox-diagram__DropdownMenuItem {
  justify-content: flex-start;
  width: 100%;
  // height: 32px;
  padding: 8px 16px;
  white-space: normal;

  .lassox-diagram__BaseButton_leading-icon,
  .lassox-diagram__BaseButton_trailing-icon {
    margin: -1px 0;
  }

  .lassox-diagram__BaseButton_leading-icon {
    margin-left: -4px;
  }

  .lassox-diagram__BaseButton_trailing-icon {
    margin-left: auto;
    margin-right: -4px;
  }

  .lassox-diagram__BaseButton_label {
    line-height: 16px;
  }

  .lassox-diagram__BaseButton_leading-icon + .lassox-diagram__BaseButton_label,
  .lassox-diagram__BaseButton_label + .lassox-diagram__BaseButton_trailing-icon {
    padding-left: 12px;
  }
}
</style>
